// Bundles drizzle migrations into a TS module so Workers (no filesystem) can run them.
// Output shape matches drizzle-orm/durable-sqlite/migrator: {journal, migrations: {m0000: sql}}.
import {readFileSync, writeFileSync} from "node:fs";
import {join} from "node:path";

const root = join(import.meta.dirname, "..");
const migrationsDir = join(root, "packages/shared/src/db/migrations");
const outFile = join(root, "packages/shared/src/db/migrations-bundle.generated.ts");

/** @type {unknown} */
const parsed = JSON.parse(readFileSync(join(migrationsDir, "meta/_journal.json"), "utf8"));
// oxlint-disable-next-line typescript/no-unsafe-type-assertion -- trusted drizzle-kit output
const journal = /** @type {{entries: {idx: number, tag: string}[]}} */ (parsed);
/** @type {Record<string, string>} */
const migrations = {};
for (const entry of journal.entries) {
	migrations[`m${String(entry.idx).padStart(4, "0")}`] = readFileSync(
		join(migrationsDir, `${entry.tag}.sql`),
		"utf8",
	);
}

const out = `// Generated by scripts/gen-migrations-bundle.mjs. Do not edit.
export const journal = ${JSON.stringify(journal, null, "\t")} as const;

export const migrations: Record<string, string> = ${JSON.stringify(migrations, null, "\t")};
`;
writeFileSync(outFile, out);
